/** Crockford base32 ULID, as generated by the server. */
export const ULID_RE = /^[0-9A-HJKMNP-TV-Z]{26}$/;

/** Mention token stored in message bodies: <@USER_ULID> (D-32). */
export const MENTION_TOKEN_RE = /<@([0-9A-HJKMNP-TV-Z]{26})>/g;

export function mentionToken(userId: string): string {
  return `<@${userId}>`;
}

/** Unique user IDs mentioned in a body, in order of first appearance. */
export function extractMentionIds(body: string | null | undefined): string[] {
  if (!body) return [];
  const ids = new Set<string>();
  for (const match of body.matchAll(MENTION_TOKEN_RE)) ids.add(match[1]!);
  return [...ids];
}

function stripDiacritics(value: string): string {
  return value.normalize('NFKD').replace(/\p{M}/gu, '');
}

/** Display name as shown: NFC, trimmed, inner whitespace collapsed, case kept. */
export function cleanDisplayName(name: string): string {
  return name.normalize('NFKC').replace(/\s+/g, ' ').trim();
}

/**
 * Uniqueness key for display names (D-32): "José", "jose " and "JOSÉ" all collide.
 */
export function nameKey(name: string): string {
  return stripDiacritics(cleanDisplayName(name)).toLowerCase();
}

/** Room slug: "Futebol & Cia" → "futebol-cia". Empty string if nothing usable remains. */
export function slugify(name: string): string {
  return stripDiacritics(name)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
    .replace(/-+$/g, '');
}

const PICTOGRAPHIC = /\p{Extended_Pictographic}|\p{Regional_Indicator}/u;
const EMOJI_ONLY =
  /^(?:\p{Extended_Pictographic}|\p{Emoji_Component}|\p{Regional_Indicator}|‍|️|⃣)+$/u;

/** True for a single emoji or a short emoji sequence, never for text. */
export function isEmoji(value: string): boolean {
  return (
    value.length > 0 && value.length <= 16 && EMOJI_ONLY.test(value) && PICTOGRAPHIC.test(value)
  );
}
